-- V11: catálogo geográfico oficial de Oaxaca.
-- Fuente: INEGI, Catálogo Único de Claves de Áreas Geoestadísticas Estatales, Municipales y Localidades (AGEEML),
-- consulta del 12/11/2026. Región de cada municipio: por distrito (cada región es un grupo de distritos completos);
-- los totales por región coinciden con los oficiales (oaxaca.gob.mx/regiones): 121/50/68/70/45/155/41/20 = 570.
-- Es seguro correrla sobre una base donde ya creaste municipios a mano: si tienen la misma clave se actualizan,
-- y si no tenían clave y el nombre coincide se les asigna.

ALTER TABLE localidad ADD COLUMN IF NOT EXISTS clave_inegi text;
ALTER TABLE localidad ADD CONSTRAINT ck_localidad_clave CHECK (clave_inegi IS NULL OR clave_inegi ~ '^[0-9]{9}$');
CREATE UNIQUE INDEX uq_localidad_clave_inegi ON localidad (clave_inegi) WHERE clave_inegi IS NOT NULL;

CREATE TEMP TABLE tmp_mun (clave text, nombre text, region_slug text, lat double precision, lng double precision) ON COMMIT DROP;
