UPDATE municipio m SET clave_inegi = t.clave
FROM tmp_mun t
WHERE m.clave_inegi IS NULL AND lower(m.nombre) = lower(t.nombre)
  AND NOT EXISTS (SELECT 1 FROM municipio x WHERE x.clave_inegi = t.clave);

INSERT INTO municipio (region_id, clave_inegi, nombre, ubicacion)
SELECT r.id, t.clave, t.nombre, ST_SetSRID(ST_MakePoint(t.lng, t.lat), 4326)::geography
FROM tmp_mun t
JOIN destino d ON d.codigo = 'oaxaca'
JOIN region r ON r.destino_id = d.id AND r.slug = t.region_slug
ON CONFLICT (clave_inegi) DO UPDATE
  SET region_id = EXCLUDED.region_id, nombre = EXCLUDED.nombre, ubicacion = EXCLUDED.ubicacion,
      actualizado_en = now();

CREATE TEMP TABLE tmp_loc (clave text, mun text, nombre text, lat double precision, lng double precision) ON COMMIT DROP;
