INSERT INTO localidad (municipio_id, clave_inegi, nombre, ubicacion)
SELECT m.id, t.clave, t.nombre,
       CASE WHEN t.lat IS NULL OR t.lng IS NULL THEN NULL
            ELSE ST_SetSRID(ST_MakePoint(t.lng, t.lat), 4326)::geography END
FROM tmp_loc t JOIN municipio m ON m.clave_inegi = t.mun;
